import subprocess
def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    proc = subprocess.run(["git", "-C", ignored, "status", "-s", "--ignored"], capture_output=True, text=True)
    lines = proc.stdout.strip("\n").splitlines()
    result = []
    for line in lines:
        if "!" in line:
            result.append(line.replace("!", ""))
    return ", ".join(result)

